local({
  d <- demo_data("groups")
  base <- list(y = "response", group = "group", id = "subject", adjustment = "sidak")
  auto <- run_analysis(d, modifyList(base, list(method = "rm_auto")))
  check(auto$method == "rm_anova" && grepl("every subject", auto$notes[1]), "Automatic mode chooses repeated ANOVA for complete selected measurements")
  missing <- d; missing$response[2] <- NA
  auto <- run_analysis(missing, modifyList(base, list(method = "rm_auto")))
  check(auto$method == "mixed" && auto$tables$data_audit$used_rows == 23, "Automatic mode chooses mixed effects and retains available data when a value is missing")
  unobserved <- d[-2, ]
  check(run_analysis(unobserved, modifyList(base, list(method = "rm_auto")))$method == "mixed", "Automatic mode detects absent subject-condition records")
  log_auto <- run_analysis(missing, modifyList(base, list(method = "log_rm_auto")))
  check(log_auto$method == "log_mixed" && "geometric_mean_ratio" %in% names(log_auto$tables$posthoc), "Automatic lognormal mode reports geometric ratios")
  none <- run_analysis(d, modifyList(base, list(method = "mixed", comparisons = "none")))
  check(is.null(none$tables$posthoc) && !is.null(none$tables$test), "No follow-up option retains the omnibus result without creating comparisons")
  pair_key <- paste(vapply(c("Control", "Drug B"), utils::URLencode, character(1), reserved = TRUE), collapse = "::")
  selected <- run_analysis(d, modifyList(base, list(method = "mixed", comparisons = "selected", selected_pairs = pair_key)))
  all <- run_analysis(d, modifyList(base, list(method = "mixed")))
  check(nrow(selected$tables$posthoc) == 1 && near(selected$tables$posthoc$adjusted_p_value, selected$tables$posthoc$p_value) && selected$tables$posthoc$group_2 == "Drug B", "Selected comparisons correct only the selected family")
  reverse <- run_analysis(d, modifyList(base, list(method = "mixed", comparisons = "selected", selected_pairs = pair_key, reverse_comparisons = TRUE)))
  check(near(reverse$tables$posthoc$estimate, -selected$tables$posthoc$estimate) && near(reverse$tables$posthoc$ci_low, -selected$tables$posthoc$ci_high) && near(reverse$tables$posthoc$p_value, selected$tables$posthoc$p_value), "Reversing a contrast changes its sign and interval endpoints but preserves its probability")
  check(fails(run_analysis(d[d$group != "Drug B", ], modifyList(base, list(method = "anova", comparisons = "selected", selected_pairs = pair_key, adjustment = "sidak"))), "no longer valid"), "A missing selected condition cannot silently change the requested pair")
  check(identical(bky_rejections(c(.01, .04, .1, .5), .1), c(TRUE, TRUE, TRUE, FALSE)), "BKY two-stage procedure matches a hand-calculated adaptive rejection example")
  qvalues <- adjust_family(c(.01, .04, .1, .5, NA), "BKY", n = 5)
  check(identical(qvalues <= .1 & !is.na(qvalues), bky_rejections(c(.01, .04, .1, .5, NA), .1, 5)), "BKY adjusted q-values preserve discoveries with unavailable comparisons in the family")
  check(near(adjust_family(c(.2, .01, .04), "holm_sidak"), c(.2, .029701, .0784)), "Holm-Sidak adjustment matches known step-down values")
  fdr <- run_analysis(d, modifyList(base, list(method = "mixed", adjustment = "BKY", fdr_q = .1)))
  check("discovery" %in% names(fdr$tables$posthoc) && !"significant" %in% names(fdr$tables$posthoc), "FDR comparisons report discoveries at Q instead of family-wise significance")
  set.seed(618)
  n <- 24; k <- 3; covariance <- matrix(-.25, k, k); diag(covariance) <- 1
  scores <- matrix(rnorm(n*k), n, k) %*% chol(covariance)
  scores <- sweep(scores, 2, c(1, 2, 3), "+")
  negative <- data.frame(subject = rep(paste0("S", 1:n), k), group = rep(c("Baseline", "Step 1", "Step 2"), each = n), response = c(scores))
  full <- run_analysis(negative, modifyList(base, list(method = "mixed", random_effect = "full", sphericity = "none", report_goodness = TRUE, report_aicc = TRUE, report_effects = TRUE)))
  check(full$tables$variance_components$variance[1] < 0 && is.na(full$tables$variance_components$sd[1]), "Full covariance fit permits a negative subject component without inventing its SD")
  ref <- nlme::gls(y ~ group, full$data, correlation = nlme::corCompSymm(value = -.2, form = ~1 | id), method = "REML")
  check(near(full$tables$coefficients$estimate, coef(ref), 1e-6) && near(vcov(full$fit), vcov(ref), 1e-6), "Signed compound-symmetry coefficients and covariance match an independent nlme fit")
  dd <- full$data; info <- attr(full$fit, "labstats"); X <- model.matrix(~group, dd)
  V <- diag(info$residual_variance, nrow(dd)) + info$subject_variance*outer(as.character(dd$id), as.character(dd$id), "==")
  check(min(eigen(V, symmetric = TRUE)$values) > 0, "Signed subject component keeps the observation covariance positive definite")
  inverse <- solve(V); C <- solve(t(X)%*%inverse%*%X); beta <- as.numeric(C%*%t(X)%*%inverse%*%dd$y)
  manual_F <- as.numeric(t(beta[-1])%*%solve(C[-1,-1])%*%beta[-1])/(k - 1)
  check(near(full$tables$test$statistic, manual_F, 1e-6), "Full-model omnibus F matches direct block-covariance GLS algebra")
  removed <- run_analysis(negative, modifyList(base, list(method = "mixed", random_effect = "remove", sphericity = "none")))
  ordinary <- run_analysis(negative, modifyList(base, list(method = "anova", adjustment = "sidak")))
  check(removed$tables$variance_components$variance[1] == 0 && near(removed$tables$test$p_value, ordinary$tables$anova[["Pr(>F)"]][1]), "Removing a nonpositive subject effect refits the independent model and matches ordinary ANOVA")
  starts <- run_analysis(d, modifyList(base, list(method = "mixed", random_effect = "full", glm_initial = FALSE)))
  check(starts$tables$model$starts_tried == 1 && !starts$tables$model$GLM_initial_values, "Disabling GLM initialization uses just the small starting value")
  trend <- run_analysis(d, modifyList(base, list(method = "rm_anova", comparisons = "trend", sphericity = "none")))
  step <- match(d$group, unique(d$group)); trend_ref <- anova(lm(response ~ subject + step + group, d))
  check(near(trend$tables$trend$p_value, trend_ref["step", "Pr(>F)"]), "Repeated linear trend matches an independently ordered GLM decomposition")
  check(fails(run_analysis(d, modifyList(base, list(method = "mixed", comparisons = "trend", sphericity = "gg"))), "sphericity"), "Trend with GG correction is explicitly rejected")
  ranked <- data.frame(group = rep(c("A", "B", "C"), each = 3), response = 1:9)
  dunn <- run_analysis(ranked, list(method = "kruskal", group = "group", y = "response", rank_test = "dunn", adjustment = "none"))
  check(near(dunn$tables$posthoc$p_value[c(1,2)], c(.1797124948789998, .0072903580915356)), "Dunn comparison matches known normal-approximation rank probabilities")
  extras <- run_analysis(d, modifyList(base, list(method = "anova", report_goodness = TRUE, report_aicc = TRUE, report_effects = TRUE, residual_normality = TRUE, residual_variance = TRUE)))
  residuals <- residuals(extras$fit)
  check(near(extras$tables$residual_normality$p_value[c(2,4)], c(nortest::ad.test(residuals)$p.value, nortest::lillie.test(residuals)$p.value)), "Residual AD and corrected KS tests match nortest references")
  check(near(extras$tables$residual_variance$p_value[2], bartlett.test(response ~ group, d)$p.value), "Residual Bartlett test matches the raw-data variance test")
  check(near(extras$tables$effect_sizes$eta_squared, summary(lm(response ~ group, d))$r.squared), "Ordinary ANOVA eta squared matches independently computed R squared")
  mc <- extras$tables$model_comparison; K <- attr(logLik(lm(response ~ group, d)), "df")
  check(near(mc$AICc[1], AIC(lm(response ~ group, d)) + 2*K*(K + 1)/(nrow(d) - K - 1)) && near(sum(mc$Akaike_weight), 1), "AICc uses ML parameter counts and normalized model weights")
  hidden <- extras; hidden$config$report_descriptive <- FALSE; hidden$config$report_adjusted_p <- FALSE
  check(!"summary" %in% names(visible_result_tables(hidden)) && !"adjusted_p_value" %in% names(visible_result_tables(hidden)$posthoc) && !is.null(hidden$tables$summary), "Report switches hide optional outputs while retaining calculations needed by graphs")
  check(format_result_table(data.frame(p_value = .012345, estimate = 1.23456), 3, "decimal", 4)$p_value == "0.0123", "P-value formatting respects selected decimal precision")
  for (kind in c("residual", "homoscedasticity", "residual_qq", "residual_heatmap", "differences")) ggplot2::ggplot_build(make_graph(full, kind))
  ggplot2::ggplot_build(make_graph(dunn, "ranks"))
  check(TRUE, "Every new diagnostic graph builds from the intended model or ranks")
  source("R/project.R")
  p <- new_project(); t <- project_add(p, "tables", list(name = "Repeated", type = "other", layout = "long", columns = NULL, id_column = "subject", data = negative))
  a <- project_add(t$project, "analyses", list(name = "Full model", table_id = t$id, input_data = negative, config = full$config, result = full))
  g <- project_add(a$project, "graphs", list(name = "Residual QQ", analysis_id = a$id, kind = "residual_qq", options = list()))
  restored <- read_project(project_json(g$project))
  check(near(restored$analyses[[a$id]]$result$tables$test$p_value, full$tables$test$p_value, 1e-6) && restored$graphs[[g$id]]$kind == "residual_qq", "Project JSON reopens advanced signed-covariance settings and residual graphs")
  path <- file.path("artifacts", "reproduce_options.R")
  writeLines(reproduction_script(negative, full$config, graph_kind = "residual_qq"), path)
  old <- getwd(); on.exit(setwd(old), add = TRUE); script <- normalizePath(path); setwd("artifacts")
  e <- new.env(parent = globalenv()); sys.source(script, envir = e)
  setwd(old)
  check(near(e$result$tables$test$p_value, full$tables$test$p_value, 1e-6), "Standalone export reproduces advanced model settings without project-relative source files")
})
